import{_ as r,l as o,o as e,c as s,v as t,p,x as i,d as n,i as T,S as d}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"保活与半开","description":"","frontmatter":{"title":"保活与半开","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/keepalive-half-open.md","filePath":"cs/keepalive-half-open.md","lastUpdated":1789023840000}'),h={name:"cs/keepalive-half-open.md"};function c(E,a,_,A,f,m){const l=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="保活与半开" tabindex="-1">保活与半开 <a class="header-anchor" href="#保活与半开" aria-label="Permalink to &quot;保活与半开&quot;">​</a></h1><div class="epigraph"><p>对端崩溃或 NAT 超时后，本地仍显示 ESTABLISHED；保活用稀少探测把半开找出来，默认以小时计，不是心跳协议。</p><footer>—— 据 RFC 9293 保活；RFC 1122 主机需求整理</footer></div><p><a href="/cs/tcp-state-machine">状态机</a> 可停在 ESTABLISHED。<a href="/cs/syn-cookies">上一课</a> 管握手泛洪。缺口是<strong>长期半开</strong>：中间 NAT、崩溃、无线切换丢了 RST。本课不把 RTT 公平写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>TCP 无数据则无包，防火墙/NAT 会话超时后黑洞，两端还以为连接在。Keepalive：空闲超过阈值发探测 ACK/包，失败则错误给应用。默认 2 小时量级，对交互应用太慢，故应用层心跳后课。探测可被中间当成流量重置计时——副作用。SO_KEEPALIVE 是套接字选项，不是 HTTP 的 keepalive。</p><p>不要把保活写成拥塞探测。</p><p><span class="marginnote">RFC 1122 说保活可选且应能关。移动网络更短的 NAT 超时迫使应用心跳。本课钉传输层。</span></p><h3 id="默认以小时计" tabindex="-1">默认以小时计 <a class="header-anchor" href="#默认以小时计" aria-label="Permalink to &quot;默认以小时计&quot;">​</a></h3><p>不是 HTTP keepalive。交互应用应自管心跳。探测可刷新 NAT，也会阻止休眠。TIME_WAIT 不要用保活「修」。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：TCP keepalive vs 应用 ping vs QUIC PING 帧。画：空闲 → 探测 → 无应答则关闭。与 LLDP TTL 老化同类：软状态需要刷新。</p>',11)),(e(),p(d,null,{default:i(()=>[T(l,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20IDLE%5B%22%E7%A9%BA%E9%97%B2%20ESTABLISHED%22%5D%20--%3E%20KA%5B%22keepalive%20%E6%8E%A2%E6%B5%8B%22%5D%0A%20%20KA%20--%3E%20OK%5B%22%E5%88%B7%E6%96%B0%E4%B8%AD%E9%97%B4%E7%8A%B6%E6%80%81%22%5D%0A%20%20KA%20--%3E%20DEAD%5B%22%E5%A4%B1%E8%B4%A5%E5%88%99%E6%8B%86%E8%BF%9E%E6%8E%A5%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>半开浪费 TCB 与 NAT 槽。RST 若走过仍能立刻拆；保活是 RST 丢失时的底。卫星贵流量，不宜高频探测。RoCE QP 有自己的超时。状态 TIME_WAIT 不是半开，不要用保活「修」。</p><p>与端到端：只有应用知道「会话是否还有意义」，传输保活只知对端栈是否应答。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 TCP_USER_TIMEOUT 的全部。RTT 不公平是下一课。后课默认：TCP keepalive 慢且可选；短超时用应用心跳。</p><p>在电池设备上保活会阻止休眠。</p><p>上一课留下的缺口在本课收口；「保活与半开」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/cc-fairness-rtt">RTT 不公平</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>半开：状态还在，路已断。</li><li>传输保活以小时计，刷新 NAT。</li><li>交互应用应自管心跳。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 9293；RFC 1122。</li></ul>',10))])}const P=r(h,[["render",c]]);export{B as __pageData,P as default};
